import { Accessor, createContext, createMemo, createSignal, onCleanup, Setter, useContext } from "solid-js";
import { createMutable } from "solid-js/store";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { FocusContextProvider } from "#core/ui-next/services/focus.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";
import { LayoutModel } from "#core/ui-next/utilities/layout-utilities.js";

import {
	activeCrisisCards,
	activePolicyCards,
	activeTraditionCards,
	availableCrisisCards,
	availablePolicyCards,
	availableTraditionCards,
	setActiveCrisisCards,
	setActivePolicyCards,
	setActiveTraditionCards,
	setAvailableCrisisCards,
	setAvailablePolicyCards,
	setAvailableTraditionCards,
} from "#base/ui/policies/policies-support.js";

export interface PolicyCardContext {
	activePolicies: TraditionDefinition[];
	availablePolicies: TraditionDefinition[];
	activeTraditions: TraditionDefinition[];
	availableTraditions: TraditionDefinition[];
	activeCrisisPolicies: TraditionDefinition[];
	availableCrisisPolicies: TraditionDefinition[];
	newCards: TraditionDefinition[];
	numSlots: number;
	policySlots: number;
	tradSlots: number;
	crisisSlots: number;
	canSwapPolicies: boolean;
	canSwapCrisis: boolean;
	confirmDisable: boolean;
	onCardClick: (card: TraditionDefinition, active: boolean, tradSlot: boolean) => void;
	onConfirmClick: () => void;
	onCloseClick: () => void;
	isSmallScreen: () => boolean;
	clearArrays: () => void;
	canSlotCard: (card: TraditionDefinition) => boolean;
	setActiveFocus: Setter<FocusContextProvider | null>;
	getActiveFocus: Accessor<FocusContextProvider | null>;
	setAvailablePolicyFocus: Setter<FocusContextProvider | null>;
	getAvailablePolicyFocus: Accessor<FocusContextProvider | null>;
	setAvailableTraditionFocus: Setter<FocusContextProvider | null>;
	getAvailableTraditionFocus: Accessor<FocusContextProvider | null>;
	autoFocusCard: number;
}

export enum PolicyCardIdeology {
	NONE,
	COMMUNISM,
	DEMOCRACY,
	FASCISM,
	TRADITION,
}

export interface AvailablePolicyProps {
	data: TraditionDefinition[];
}

export interface ActivePolicyProps {
	data: TraditionDefinition[];
}

let policiesToAdd: TraditionDefinition[] = [];
let policiesToRemove: TraditionDefinition[] = [];
let policiesWasTradition: TraditionDefinition[] = [];

const allActive = createMemo(() => [...activeTraditionCards, ...activePolicyCards]);

export function createPoliciesModel() {
	onCleanup(() => {
		clearArrays();
		handleConsideredPolicies();
	});
	let _activePolicies: TraditionDefinition[] = [];
	let _availablePolicies: TraditionDefinition[] = [];
	let _activeTraditions: TraditionDefinition[] = [];
	let _availableTraditions: TraditionDefinition[] = [];
	let _activeCrisisPolicies: TraditionDefinition[] = [];
	let _availableCrisisPolicies: TraditionDefinition[] = [];

	let _slots = 0;
	let _policySlots = 0;
	let _tradSlots = 0;
	let _crisisSlots = 0;

	const [availableTraditionFocus, setAvailableTraditionFocus] = createSignal<FocusContextProvider | null>(null);
	const [availablePolicyFocus, setAvailablePolicyFocus] = createSignal<FocusContextProvider | null>(null);
	const [activeFocus, setActiveFocus] = createSignal<FocusContextProvider | null>(null);

	const localPlayer: PlayerLibrary | null = Players.get(GameContext.localPlayerID);

	const localPlayerCulture: PlayerCulture = localPlayer!.Culture!;

	const unlockedPolicies: TraditionType[] = localPlayerCulture.getUnlockedTraditions(
		CultureSlotTypes.POLICY_CULTURE_SLOT,
	);
	const unlockedTraditions: TraditionType[] = localPlayerCulture.getUnlockedTraditions(
		CultureSlotTypes.TRADITION_CULTURE_SLOT,
	);

	const unlockedCrises: TraditionType[] = localPlayerCulture.getUnlockedTraditions(
		CultureSlotTypes.CRISIS_CULTURE_SLOT,
	);
	_slots = localPlayerCulture.getNumAllCultureSlots();
	_tradSlots = localPlayerCulture.getNumCultureSlots(CultureSlotTypes.TRADITION_CULTURE_SLOT);
	_policySlots = localPlayerCulture.getNumCultureSlots(CultureSlotTypes.POLICY_CULTURE_SLOT);
	_crisisSlots = localPlayerCulture.getNumCultureSlots(CultureSlotTypes.CRISIS_CULTURE_SLOT);

	const canSwapNormalPolicies = localPlayerCulture.canSwapCultureSlot(
		CultureSlotTypes.POLICY_CULTURE_SLOT || CultureSlotTypes.TRADITION_CULTURE_SLOT,
	);

	const canSwapCrisisPolicies = localPlayerCulture.canSwapCultureSlot(CultureSlotTypes.CRISIS_CULTURE_SLOT);

	const newTraditionsAndPolicies: TraditionType[] = localPlayerCulture.getAllRecentUnlockedTraditions();
	const newCardsDot: TraditionDefinition[] = [];

	for (const item of newTraditionsAndPolicies) {
		const newItem = GameInfo.Traditions.lookup(item)!;
		newCardsDot.push(newItem);
	}

	//these values need to match the media query values in the screen-policies.scss
	const SMALL_SCREEN_MODE_MAX_HEIGHT = 1000;
	const SMALL_SCREEN_MODE_MAX_WIDTH = 1700;

	const layout = LayoutModel.get();
	const isSmallScreenSize = createMemo(() => {
		const isMobileViewExperience = UI.getViewExperience() == UIViewExperience.Mobile;
		return (
			isMobileViewExperience ||
			layout.screenHeight() <= Layout.pixelsToScreenPixels(SMALL_SCREEN_MODE_MAX_HEIGHT) ||
			layout.screenWidth() <= Layout.pixelsToScreenPixels(SMALL_SCREEN_MODE_MAX_WIDTH) ||
			layout.screenWidth() / layout.screenHeight() < 1.34
		);
	});

	//these are the card values directly from database to use as reference to build card stores on init
	function getAvailablePolicies() {
		_availablePolicies = [];
		for (const policyTypeHash of unlockedPolicies) {
			const policyInfo: TraditionDefinition | null = GameInfo.Traditions.lookup(policyTypeHash);
			if (policyInfo && !localPlayerCulture.isTraditionActive(policyTypeHash)) {
				_availablePolicies.push(policyInfo);
			}
		}
		return _availablePolicies.reverse();
	}

	function getAvailableTraditions() {
		_availableTraditions = [];
		for (const policyTypeHash of unlockedTraditions) {
			const policyInfo: TraditionDefinition | null = GameInfo.Traditions.lookup(policyTypeHash);
			if (policyInfo && !localPlayerCulture.isTraditionActive(policyTypeHash)) {
				_availableTraditions.push(policyInfo);
			}
		}
		return _availableTraditions.reverse();
	}

	function getAvailableCrises() {
		_availableCrisisPolicies = [];
		for (const policyTypeHash of unlockedCrises) {
			const policyInfo: TraditionDefinition | null = GameInfo.Traditions.lookup(policyTypeHash);
			if (policyInfo && !localPlayerCulture.isTraditionActive(policyTypeHash)) {
				_availableCrisisPolicies.push(policyInfo);
			}
		}
		return _availableCrisisPolicies.reverse();
	}
	function getActivePolicies() {
		_activePolicies = [];
		const activeLaws: TraditionType[] = localPlayerCulture.getActiveTraditions(
			CultureSlotTypes.POLICY_CULTURE_SLOT,
		);

		for (const policy of activeLaws) {
			const policyDef = GameInfo.Traditions.lookup(policy);
			if (policyDef) {
				_activePolicies.push(policyDef);
			}
		}

		return _activePolicies;
	}
	function getActiveTraditions() {
		_activeTraditions = [];
		const activeTraditions: TraditionType[] = localPlayerCulture.getActiveTraditions(
			CultureSlotTypes.TRADITION_CULTURE_SLOT,
		);

		for (const policy of activeTraditions) {
			const policyDef = GameInfo.Traditions.lookup(policy);
			if (policyDef) {
				_activeTraditions.push(policyDef);
			}
		}

		return _activeTraditions;
	}

	function getActiveCrises() {
		_activeCrisisPolicies = [];
		const activeCrises: TraditionType[] = localPlayerCulture.getActiveTraditions(
			CultureSlotTypes.CRISIS_CULTURE_SLOT,
		);
		for (const policy of activeCrises) {
			const policyDef = GameInfo.Traditions.lookup(policy);
			if (policyDef) {
				_activeCrisisPolicies.push(policyDef);
			}
		}
		return _activeCrisisPolicies;
	}

	const tradSlotsAvail = createMemo(() => _tradSlots - activeTraditionCards.length);
	const policySlotsAvail = createMemo(() => _policySlots - activePolicyCards.length);
	const crisisSlotsAvail = createMemo(() => _crisisSlots - activeCrisisCards.length);

	function moveItem(
		card: TraditionDefinition,
		source: TraditionDefinition[],
		setSource: (v: TraditionDefinition[]) => void,
		setTarget: (v: TraditionDefinition[]) => void,
		target: TraditionDefinition[],
	): void {
		const item = source.find((i) => i === card);
		if (!item) return;

		setSource(source.filter((i) => i !== card));
		setTarget([...target, item]);
	}

	// helper functions for moving cards
	const policyToActive = (card: TraditionDefinition) =>
		moveItem(card, availablePolicyCards, setAvailablePolicyCards, setActivePolicyCards, activePolicyCards);

	const policyToAvailable = (card: TraditionDefinition) =>
		moveItem(card, activePolicyCards, setActivePolicyCards, setAvailablePolicyCards, availablePolicyCards);

	const policyToTradition = (card: TraditionDefinition) =>
		moveItem(card, availablePolicyCards, setAvailablePolicyCards, setActiveTraditionCards, activeTraditionCards);

	const traditionToPolicy = (card: TraditionDefinition) =>
		moveItem(card, activeTraditionCards, setActiveTraditionCards, setAvailablePolicyCards, availablePolicyCards);

	const traditionToActive = (card: TraditionDefinition) =>
		moveItem(
			card,
			availableTraditionCards,
			setAvailableTraditionCards,
			setActiveTraditionCards,
			activeTraditionCards,
		);

	const traditionToAvailable = (card: TraditionDefinition) =>
		moveItem(
			card,
			activeTraditionCards,
			setActiveTraditionCards,
			setAvailableTraditionCards,
			availableTraditionCards,
		);

	const crisisToActive = (card: TraditionDefinition) =>
		moveItem(card, availableCrisisCards, setAvailableCrisisCards, setActiveCrisisCards, activeCrisisCards);

	const crisisToAvailable = (card: TraditionDefinition) =>
		moveItem(card, activeCrisisCards, setActiveCrisisCards, setAvailableCrisisCards, availableCrisisCards);

	const activeTraditionToActivePolicy = (card: TraditionDefinition) =>
		moveItem(card, activeTraditionCards, setActiveTraditionCards, setActivePolicyCards, activePolicyCards);

	function isInTradSlot(card: TraditionDefinition) {
		if (activeTraditionCards.includes(card)) {
			return true;
		} else {
			return false;
		}
	}

	function fallbackPolicyFocus(card: TraditionDefinition) {
		if (availableTraditionCards.length > 0) {
			model.autoFocusCard = availableTraditionCards[availableTraditionCards.indexOf(card) + 1].$index ?? -1;
		} else {
			model.autoFocusCard = allActive()[allActive().indexOf(card) + 1].$index ?? -1;
		}
	}

	function fallbackTraditionFocus(card: TraditionDefinition) {
		if (availablePolicyCards.length > 0) {
			model.autoFocusCard = availablePolicyCards[availablePolicyCards.indexOf(card) + 1].$index ?? -1;
		} else {
			model.autoFocusCard = allActive()[allActive().indexOf(card) + 1].$index ?? -1;
		}
	}

	function fallbackActivePolicyFocus(card: TraditionDefinition) {
		if (availableTraditionCards.length > 0) {
			model.autoFocusCard = availableTraditionCards[availableTraditionCards.indexOf(card) + 1].$index ?? -1;
		} else {
			model.autoFocusCard = availablePolicyCards[availablePolicyCards.indexOf(card) + 1].$index ?? -1;
		}
	}

	function resolveLocalFocus(card: TraditionDefinition) {
		//we don't need to guide focus on the crisis screen because its a simpler layout
		if (activeCrisisCards.includes(card) || availableCrisisCards.includes(card)) {
			return;
		}
		//set focus flow if card is leaving the available policies column, the leftmost column
		if (availablePolicyCards.includes(card)) {
			//check if the first card or last card in the column to select the next card instead of previous card for pending focus
			if (availablePolicyCards.indexOf(card) == 0) {
				if (availablePolicyCards.length > 1) {
					model.autoFocusCard = availablePolicyCards[availablePolicyCards.indexOf(card) + 1].$index ?? -1;
					return;
				} else {
					fallbackPolicyFocus(card); //if last card fallback to next column
					return;
				}
			}
			model.autoFocusCard = availablePolicyCards[availablePolicyCards.indexOf(card) - 1].$index ?? -1;
			if (model.autoFocusCard == -1) {
				fallbackPolicyFocus(card);
			}
		}
		//set focus flow if card is leaving the available traditions column, the second leftmost column
		if (availableTraditionCards.includes(card)) {
			//check if the first card or last card in the column to select the next card instead of previous card for pending focus
			if (availableTraditionCards.indexOf(card) == 0) {
				if (availableTraditionCards.length > 1) {
					model.autoFocusCard =
						availableTraditionCards[availableTraditionCards.indexOf(card) + 1].$index ?? -1;
					return;
				} else {
					fallbackTraditionFocus(card); //if last card fallback to next column
					return;
				}
			}
			model.autoFocusCard = availableTraditionCards[availableTraditionCards.indexOf(card) - 1].$index ?? -1;
			if (model.autoFocusCard == -1) {
				fallbackTraditionFocus(card);
			}
		}
		//set focus flow if card is leaving the active column, this is the double column on the right
		if (allActive().includes(card)) {
			//check if the first card or last card in the column to select the next card instead of previous card for pending focus
			if (allActive().indexOf(card) == 0) {
				if (allActive().length > 1) {
					model.autoFocusCard = allActive()[allActive().indexOf(card) + 1].$index ?? -1;
					return;
				} else {
					fallbackActivePolicyFocus(card); //if last card fallback to next column
					return;
				}
			}
			model.autoFocusCard = allActive()[allActive().indexOf(card) - 1].$index ?? -1;
			if (model.autoFocusCard == -1) {
				fallbackActivePolicyFocus(card);
			}
		}
	}

	function handleOnCardClick(card: TraditionDefinition, active: boolean) {
		if (IsControllerActive()) {
			resolveLocalFocus(card);
		}

		if (active) {
			activeToAvailable(card);
			if (policiesToAdd.includes(card)) {
				const index: number = policiesToAdd.indexOf(card);
				policiesToAdd.splice(index, 1);
			} else {
				policiesToRemove.push(card);
			}
		} else {
			if (availableToActive(card)) {
				if (policiesToRemove.includes(card) && !policiesWasTradition.includes(card)) {
					const index: number = policiesToRemove.indexOf(card);
					policiesToRemove.splice(index, 1);
				} else {
					policiesToAdd.push(card);
				}
			}
		}
	}

	function activeToAvailable(card: TraditionDefinition) {
		const c = card.CultureSlotType;

		if (c == "CRISIS_CULTURE_SLOT") {
			crisisToAvailable(card);
		}
		if (c == "POLICY_CULTURE_SLOT" && !isInTradSlot(card)) {
			policyToAvailable(card);
		}
		if (c == "POLICY_CULTURE_SLOT" && isInTradSlot(card)) {
			traditionToPolicy(card);

			if (!policiesWasTradition.includes(card)) {
				policiesWasTradition.push(card);
			}
		} else if (c == "TRADITION_CULTURE_SLOT") {
			traditionToAvailable(card);
		}
	}

	function availableToActive(card: TraditionDefinition) {
		const c = card.CultureSlotType;

		if (c == "CRISIS_CULTURE_SLOT") {
			if (crisisSlotsAvail() < 1) {
				return false;
			}
			crisisToActive(card);
			return true;
		}
		if (c == "POLICY_CULTURE_SLOT") {
			if (policySlotsAvail() < 1 && tradSlotsAvail() > 0) {
				policyToTradition(card);
				return true;
			} else if (policySlotsAvail() > 0) {
				policyToActive(card);
				return true;
			} else {
				return false;
			}
		}
		if (c == "TRADITION_CULTURE_SLOT") {
			if (tradSlotsAvail() > 0) {
				traditionToActive(card);
				return true;
			}
			//this is for edge cases when moving a policy that is in a tradition slot to an open policy slot if possible when a tradition is clicked and there is no open tradition slots, essentially, kicking the policy card out of the tradition slot so your tradition can go there since traditions can ONLY go in policy slots
			const policiesInTraditionSlots = activeTraditionCards.filter(
				(card) => card.CultureSlotType == "POLICY_CULTURE_SLOT",
			);

			if (policiesInTraditionSlots.length > 0 && policySlotsAvail() > 0) {
				const movingCard = policiesInTraditionSlots[0];
				activeTraditionToActivePolicy(movingCard);
				traditionToActive(card);
				if (!policiesWasTradition.includes(movingCard)) {
					policiesWasTradition.push(movingCard);
				}
				if (policiesToAdd.includes(movingCard)) {
					const index: number = policiesToAdd.indexOf(movingCard);
					policiesToAdd.splice(index, 1);
				} else {
					policiesToRemove.push(movingCard);
				}
				if (policiesToRemove.includes(movingCard) && !policiesWasTradition.includes(movingCard)) {
					const index: number = policiesToRemove.indexOf(movingCard);
					policiesToRemove.splice(index, 1);
				} else {
					policiesToAdd.push(movingCard);
				}
				return true;
			} else {
				return false;
			}
		}
		return false;
	}

	function handleCanSlotCard(card: TraditionDefinition): boolean {
		// Matches the underlying logic of availableToActive(),
		// but without actually moving the card.
		const c = card.CultureSlotType;
		if (c == "CRISIS_CULTURE_SLOT") {
			return crisisSlotsAvail() > 0;
		} else if (c == "POLICY_CULTURE_SLOT") {
			if (policySlotsAvail() < 1 && tradSlotsAvail() > 0) {
				return true;
			} else if (policySlotsAvail() > 0) {
				return true;
			}
			return false;
		} else if (c == "TRADITION_CULTURE_SLOT") {
			if (tradSlotsAvail() > 0) {
				return true;
			}
			const policiesInTraditionSlots = activeTraditionCards.filter(
				(card) => card.CultureSlotType == "POLICY_CULTURE_SLOT",
			);
			if (policiesInTraditionSlots.length > 0 && policySlotsAvail() > 0) {
				return true;
			}
		}
		return false;
	}

	function clearArrays() {
		//clear out UI only arrays
		policiesToAdd = [];
		policiesToRemove = [];
		policiesWasTradition = [];
		_activeCrisisPolicies = [];
		_activePolicies = [];
		_activeTraditions = [];
		_availableCrisisPolicies = [];
		_availablePolicies = [];
		_availableTraditions = [];
		setActivePolicyCards([]);
		setActiveTraditionCards([]);
		setActiveCrisisCards([]);
		setAvailablePolicyCards([]);
		setAvailableTraditionCards([]);
		setAvailableCrisisCards([]);
	}

	function handleOnConfirmClick() {
		model.confirmDisable = true;
		applyNextPolicy();
	}

	function handleConsideredPolicies() {
		const result = Game.PlayerOperations.canStart(
			GameContext.localPlayerID,
			PlayerOperationTypes.CONSIDER_ASSIGN_TRADITIONS,
			{},
			false,
		);
		if (result.Success) {
			Game.PlayerOperations.sendRequest(
				GameContext.localPlayerID,
				PlayerOperationTypes.CONSIDER_ASSIGN_TRADITIONS,
				{},
			);
		}
	}

	function applyNextPolicy() {
		if (policiesToRemove.length + policiesToAdd.length == 0) {
			model.confirmDisable = false;
			handleOnClose();
			return;
		}
		let policy: TraditionDefinition | undefined = undefined;
		let operationParameter: PlayerOperationParameters | null = null;

		if (policiesToRemove.length > 0) {
			policy = policiesToRemove.pop();

			operationParameter = PlayerOperationParameters.Deactivate;
		} else if (policiesToAdd.length > 0) {
			policy = policiesToAdd.pop();

			operationParameter = PlayerOperationParameters.Activate;
		}

		if (policy && operationParameter) {
			const args = {
				TraditionType: policy.$index,
				Action: operationParameter,
			};
			const result = Game.PlayerOperations.canStart(
				GameContext.localPlayerID,
				PlayerOperationTypes.CHANGE_TRADITION,
				args,
				false,
			);
			if (result.Success) {
				Game.PlayerOperations.sendRequest(
					GameContext.localPlayerID,
					PlayerOperationTypes.CHANGE_TRADITION,
					args,
				);
				const eventHandle: EventHandle = engine.on("TraditionChanged", () => {
					applyNextPolicy();
					eventHandle.clear();
				});
			} else {
				console.error(
					"screen-policies: applyNextPolicy(): Unable to successfully activate/deactivate policy with index: ",
					policy.$index,
					" and type: ",
					policy.TraditionType,
				);
			}
		} else {
			console.error("screen-policies: applyNextPolicy() - failed to start a tradition change operation!");
		}
	}

	function handleOnClose() {
		ContextManager.pop("screen-policies");
	}

	const model = createMutable<PolicyCardContext>({
		activePolicies: getActivePolicies(),
		availablePolicies: getAvailablePolicies(),
		activeTraditions: getActiveTraditions(),
		availableTraditions: getAvailableTraditions(),
		activeCrisisPolicies: getActiveCrises(),
		availableCrisisPolicies: getAvailableCrises(),
		newCards: newCardsDot,
		numSlots: _slots,
		policySlots: _policySlots,
		tradSlots: _tradSlots,
		crisisSlots: _crisisSlots,
		canSwapPolicies: canSwapNormalPolicies,
		canSwapCrisis: canSwapCrisisPolicies,
		confirmDisable: false,
		isSmallScreen: isSmallScreenSize,
		onCardClick: handleOnCardClick,
		onConfirmClick: handleOnConfirmClick,
		onCloseClick: handleOnClose,
		clearArrays: clearArrays,
		canSlotCard: handleCanSlotCard,
		setActiveFocus: setActiveFocus,
		getActiveFocus: activeFocus,
		setAvailablePolicyFocus: setAvailablePolicyFocus,
		getAvailablePolicyFocus: availablePolicyFocus,
		setAvailableTraditionFocus: setAvailableTraditionFocus,
		getAvailableTraditionFocus: availableTraditionFocus,
		autoFocusCard: -1,
	});

	return model;
}
//#region model registry / init
export const PoliciesModel = ModelRegistry.register(
	"PoliciesScreenModel",
	ModelLifecycle.SharedInstance,
	createPoliciesModel,
);

export const PoliciesModelContext = createContext<PolicyCardContext>();

export function usePoliciesModelContext() {
	const context = useContext(PoliciesModelContext);

	if (!context) {
		throw new Error("usePoliciesModelContext: Cannot find context!");
	}

	return context;
}
